# Parse a comma-separated trait list.
parse_trait_list <- function(x) {
  if (is.null(x) || nchar(trimws(x)) == 0L) {
    return(character(0))
  }

  vals <- trimws(strsplit(x, ",", fixed = TRUE)[[1]])
  unique(vals[nchar(vals) > 0L])
}

# Convert a two-sided p-value to an unsigned z-score safely.
p_to_z_safe <- function(p, cap = 8.2) {
  p <- as.numeric(p)

  p_clamped <- pmax(
    pmin(p, 1 - .Machine$double.eps),
    .Machine$double.eps
  )

  z <- qnorm(1 - p_clamped / 2)
  pmin(pmax(z, 0), cap)
}

# Remove the Ensembl version suffix.
strip_gene_version <- function(gene_ids) {
  sub("\\..*$", "", as.character(gene_ids))
}

# Align a data.table to a reference key vector.
#
# This function uses explicit key matching rather than relying on row sorting.
# It stops if any reference identifier is missing or duplicated.
align_to_reference <- function(dt, key_col, reference_keys, data_label) {
  if (!key_col %in% names(dt)) {
    stop(sprintf(
      "Required key column '%s' is missing from %s.",
      key_col,
      data_label
    ))
  }

  data_keys <- as.character(dt[[key_col]])
  reference_keys <- as.character(reference_keys)

  duplicated_data_keys <- unique(data_keys[duplicated(data_keys)])
  if (length(duplicated_data_keys) > 0L) {
    stop(sprintf(
      "%s contains duplicated values in '%s'. Examples: %s",
      data_label,
      key_col,
      paste(head(duplicated_data_keys, 10), collapse = ", ")
    ))
  }

  duplicated_reference_keys <- unique(
    reference_keys[duplicated(reference_keys)]
  )
  if (length(duplicated_reference_keys) > 0L) {
    stop(sprintf(
      "The reference list contains duplicated identifiers. Examples: %s",
      paste(head(duplicated_reference_keys, 10), collapse = ", ")
    ))
  }

  idx <- match(reference_keys, data_keys)

  if (anyNA(idx)) {
    missing_keys <- reference_keys[is.na(idx)]

    stop(sprintf(
      paste0(
        "%s does not contain all identifiers from the original reference list. ",
        "Missing: %d. Examples: %s"
      ),
      data_label,
      length(missing_keys),
      paste(head(missing_keys, 10), collapse = ", ")
    ))
  }

  aligned_dt <- dt[idx]

  if (!identical(
    as.character(aligned_dt[[key_col]]),
    reference_keys
  )) {
    stop("Internal alignment failure for ", data_label)
  }

  aligned_dt
}

# Validate a numeric vector before FDRreg.
validate_numeric_vector <- function(x, label) {
  if (!is.numeric(x)) {
    x <- suppressWarnings(as.numeric(x))
  }

  if (length(x) == 0L) {
    stop(label, " is empty.")
  }

  bad <- !is.finite(x)
  if (any(bad)) {
    stop(sprintf(
      "%s contains %d non-finite values.",
      label,
      sum(bad)
    ))
  }

  x
}

