get_magma_input_file <- function(trait_name) {
  file.path(
    magma_input_dir,
    paste0(trait_name, ".overlap.4magma.txt")
  )
}

read_magma_z <- function(trait_name) {
  input_file <- get_magma_input_file(trait_name)

  if (!file.exists(input_file)) {
    stop(
      "MAGMA input file not found for trait '",
      trait_name,
      "': ",
      input_file
    )
  }

  header <- names(fread(input_file, nrows = 0L))
  required_columns <- c("snpid", "z.decor")
  missing_columns <- setdiff(required_columns, header)

  if (length(missing_columns) > 0L) {
    stop(
      "Required columns missing from ",
      input_file,
      ": ",
      paste(missing_columns, collapse = ", ")
    )
  }

  dt <- fread(
    input_file,
    select = required_columns
  )

  if (nrow(dt) == 0L) {
    stop("MAGMA input file is empty: ", input_file)
  }

  dt[, snpid := as.character(snpid)]

  if (anyNA(dt$snpid) || any(dt$snpid == "")) {
    stop("Missing or empty snpid values found in: ", input_file)
  }

  if (anyDuplicated(dt$snpid)) {
    duplicated_ids <- unique(dt$snpid[duplicated(dt$snpid)])

    stop(
      "Duplicated snpid values found in ",
      input_file,
      ". Examples: ",
      paste(head(duplicated_ids, 10), collapse = ", ")
    )
  }

  dt[, z.decor := validate_numeric_vector(
    z.decor,
    paste0("z.decor for ", trait_name)
  )]

  dt
}

