# ---- MAGMA helper functions ---- #

# Detect the MAGMA gene identifier column.
# MAGMA .genes.out usually uses GENE, while some downstream FDRreg files use ID.
detect_magma_gene_column <- function(dt, data_label) {
  candidates <- c("GENE", "ID")
  matched <- candidates[candidates %in% names(dt)]

  if (length(matched) == 0L) {
    stop(
      "No MAGMA gene identifier column was found in ",
      data_label,
      ". Expected one of: ",
      paste(candidates, collapse = ", "),
      ". Available columns: ",
      paste(names(dt), collapse = ", ")
    )
  }

  matched[1]
}

# Detect the MAGMA p-value column.
detect_magma_p_column <- function(dt, data_label) {
  candidates <- c("P", "p", "pvalue", "PVAL", "pval")
  matched <- candidates[candidates %in% names(dt)]

  if (length(matched) == 0L) {
    stop(
      "No p-value column was found in ",
      data_label,
      ". Expected one of: ",
      paste(candidates, collapse = ", "),
      ". Available columns: ",
      paste(names(dt), collapse = ", ")
    )
  }

  matched[1]
}

# Add a standardized character gene identifier column.
standardize_magma_gene_id <- function(dt, data_label) {
  gene_col <- detect_magma_gene_column(dt, data_label)

  dt[, GENE_KEY := trimws(as.character(get(gene_col)))]

  if (anyNA(dt$GENE_KEY) || any(dt$GENE_KEY == "")) {
    stop(
      "Missing or empty MAGMA gene identifiers found in ",
      data_label,
      "."
    )
  }

  duplicated_ids <- unique(dt$GENE_KEY[duplicated(dt$GENE_KEY)])

  if (length(duplicated_ids) > 0L) {
    stop(
      "Duplicated MAGMA gene identifiers found in ",
      data_label,
      ". Examples: ",
      paste(head(duplicated_ids, 10), collapse = ", ")
    )
  }

  attr(dt, "original_gene_column") <- gene_col
  dt
}

