cat("\nLoading MAGMA gene output files...\n")

target_magma_file <- file.path(
  magma_output_dir,
  paste0(target_name, ".genes.out")
)

if (!file.exists(target_magma_file)) {
  warning("Target MAGMA file not found: ", target_magma_file)
} else {
  target_magma <- fread(target_magma_file)

  target_magma <- standardize_magma_gene_id(
    target_magma,
    paste0("target MAGMA output: ", target_magma_file)
  )

  target_p_column <- detect_magma_p_column(
    target_magma,
    paste0("target MAGMA output: ", target_magma_file)
  )

  # Store the p-value in a standardized column.
  target_magma[, P_VALUE := suppressWarnings(
    as.numeric(get(target_p_column))
  )]

  if (any(!is.finite(target_magma$P_VALUE))) {
    stop(
      "Non-finite MAGMA p-values found in target file: ",
      target_magma_file
    )
  }

  if (any(target_magma$P_VALUE < 0 | target_magma$P_VALUE > 1)) {
    stop(
      "MAGMA p-values outside [0, 1] found in target file: ",
      target_magma_file
    )
  }

  target_gene_column <- attr(
    target_magma,
    "original_gene_column"
  )

  cat(sprintf(
    "  Loaded target MAGMA: %s; gene column = %s; p-value column = %s\n",
    target_name,
    target_gene_column,
    target_p_column
  ))

  # ---- Load trait MAGMA outputs ---- #

  trait_magma_data <- list()
  valid_magma_traits <- character(0)

  for (trait in all_traits) {
    trait_file <- file.path(
      magma_output_dir,
      paste0(trait, ".genes.out")
    )

    if (!file.exists(trait_file)) {
      warning(sprintf(
        "  MAGMA file not found: %s",
        trait_file
      ))
      next
    }

    dt <- fread(trait_file)

    # Detect and standardize the gene identifier.
    gene_detection <- tryCatch(
      {
        dt <- standardize_magma_gene_id(
          dt,
          paste0("MAGMA output for ", trait, ": ", trait_file)
        )
        TRUE
      },
      error = function(e) {
        warning(conditionMessage(e))
        FALSE
      }
    )

    if (!gene_detection) {
      next
    }

    # Detect and standardize the p-value.
    p_column <- tryCatch(
      detect_magma_p_column(
        dt,
        paste0("MAGMA output for ", trait, ": ", trait_file)
      ),
      error = function(e) {
        warning(conditionMessage(e))
        NULL
      }
    )

    if (is.null(p_column)) {
      next
    }

    dt[, P_VALUE := suppressWarnings(
      as.numeric(get(p_column))
    )]

    if (any(!is.finite(dt$P_VALUE))) {
      warning(sprintf(
        "Skipping MAGMA trait '%s': non-finite p-values were found.",
        trait
      ))
      next
    }

    if (any(dt$P_VALUE < 0 | dt$P_VALUE > 1)) {
      warning(sprintf(
        "Skipping MAGMA trait '%s': p-values outside [0, 1] were found.",
        trait
      ))
      next
    }

    trait_magma_data[[trait]] <- dt
    valid_magma_traits <- c(
      valid_magma_traits,
      trait
    )

    cat(sprintf(
      "  Loaded MAGMA: %-22s gene column = %s; p-value column = %s\n",
      trait,
      attr(dt, "original_gene_column"),
      p_column
    ))
  }

  if (length(valid_magma_traits) == 0L) {
    warning("No valid MAGMA trait files found.")
  } else {
    # ---- Define the reference gene list ---- #

    if (!is.null(original_magma_gene_list)) {
      # This is the preferred branch because it guarantees that the
      # sensitivity analysis uses the exact original gene list and order.
      reference_magma_genes <- original_magma_gene_list

      cat(sprintf(
        "Using exact original MAGMA gene list and order: %d genes\n",
        length(reference_magma_genes)
      ))
    } else {
      # Fallback only when the original FDRreg result is unavailable.
      reference_magma_genes <- Reduce(
        intersect,
        c(
          list(target_magma$GENE_KEY),
          lapply(
            trait_magma_data[valid_magma_traits],
            `[[`,
            "GENE_KEY"
          )
        )
      )

      reference_magma_genes <- sort(
        unique(reference_magma_genes)
      )

      cat(sprintf(
        "Using fallback common MAGMA gene list: %d genes\n",
        length(reference_magma_genes)
      ))
    }

    if (length(reference_magma_genes) == 0L) {
      warning("No common MAGMA genes found.")
    } else {
      # ---- Align target to the original gene list ---- #

      target_magma <- align_to_reference(
        dt = target_magma,
        key_col = "GENE_KEY",
        reference_keys = reference_magma_genes,
        data_label = paste0(
          "target MAGMA output for ",
          target_name
        )
      )

      # ---- Align each trait to the same gene list and order ---- #

      aligned_trait_magma_data <- setNames(
        vector("list", length(valid_magma_traits)),
        valid_magma_traits
      )

      for (trait in valid_magma_traits) {
        aligned_trait_magma_data[[trait]] <- align_to_reference(
          dt = trait_magma_data[[trait]],
          key_col = "GENE_KEY",
          reference_keys = reference_magma_genes,
          data_label = paste0(
            "MAGMA output for ",
            trait
          )
        )
      }

      trait_magma_data <- aligned_trait_magma_data

      # Final alignment checks.
      if (!identical(
        target_magma$GENE_KEY,
        reference_magma_genes
      )) {
        stop(
          "Target MAGMA gene order does not match the reference gene list."
        )
      }

      alignment_ok <- vapply(
        trait_magma_data,
        function(dt) {
          identical(
            dt$GENE_KEY,
            reference_magma_genes
          )
        },
        logical(1)
      )

      if (!all(alignment_ok)) {
        stop(
          "MAGMA gene alignment failed for: ",
          paste(
            names(alignment_ok)[!alignment_ok],
            collapse = ", "
          )
        )
      }

      # ---- Build MAGMA feature matrix ---- #

      feature_matrix_magma <- do.call(
        cbind,
        lapply(
          trait_magma_data,
          function(dt) {
            p_to_z_safe(dt$P_VALUE)
          }
        )
      )

      # Preserve matrix structure when there is only one trait.
      if (is.null(dim(feature_matrix_magma))) {
        feature_matrix_magma <- matrix(
          feature_matrix_magma,
          ncol = 1L
        )
      }

      colnames(feature_matrix_magma) <- valid_magma_traits
      storage.mode(feature_matrix_magma) <- "double"

      if (nrow(feature_matrix_magma) != nrow(target_magma)) {
        stop(
          "MAGMA feature matrix row count does not match target gene count."
        )
      }

      if (any(!is.finite(feature_matrix_magma))) {
        stop(
          "The MAGMA feature matrix contains non-finite values."
        )
      }

      # ---- Build signed target z-scores ---- #
      #
      # MAGMA gene-level output only provides unsigned p-values.
      # Random signs are assigned using the specified seed, matching the
      # original sensitivity analysis.

      target_z_magma_unsigned <- p_to_z_safe(
        target_magma$P_VALUE
      )

      set.seed(random_seed)

      target_z_magma <- target_z_magma_unsigned *
        sign(rnorm(length(target_z_magma_unsigned)))

      if (any(!is.finite(target_z_magma))) {
        stop(
          "The target MAGMA z-score vector contains non-finite values."
        )
      }

      cat(sprintf(
        "MAGMA feature matrix: %d x %d\n",
        nrow(feature_matrix_magma),
        ncol(feature_matrix_magma)
      ))

      # ---- Run MAGMA-level FDRreg ---- #

      cat("Running FDRreg (theoretical null) for MAGMA...\n")

      fdr_magma_theoretical <- FDRreg(
        target_z_magma,
        feature_matrix_magma,
        nulltype = "theoretical",
        method = "pr"
      )

      fdr_magma <- fdr_magma_theoretical$FDR

      magma_fdr_n_sig <- sum(
        fdr_magma < sig_threshold,
        na.rm = TRUE
      )

      magma_total <- length(fdr_magma)

      cat(sprintf(
        "MAGMA fdr.the < %.2f: %d / %d\n",
        sig_threshold,
        magma_fdr_n_sig,
        magma_total
      ))

      # ---- Save MAGMA results ---- #
      #
      # Use the standardized MAGMA gene identifier. For your current data,
      # this will contain the values from ID in the original FDRreg file and
      # GENE in the .genes.out files.

      magma_results_dt <- data.table(
        GENE = target_magma$GENE_KEY,
        target_z = target_z_magma,
        fdr_the = fdr_magma
      )

      magma_output_file <- file.path(
        target_output_dir,
        paste0(
          target_name,
          "_magma_fdr_the.csv"
        )
      )

      fwrite(
        magma_results_dt,
        magma_output_file
      )

      cat(sprintf(
        "Written MAGMA sensitivity results: %s\n",
        magma_output_file
      ))
    }
  }
}

#=============================================================#
#---- PART 3: SmultiXcan SENSITIVITY ANALYSIS ----------------#
#=============================================================#

cat("\n============================================================\n")
cat("PART 3: SmultiXcan Sensitivity Analysis\n")
cat("============================================================\n")

smultixcan_output_dir <- file.path(
  base_output_path,
  target_name,
  "08.smultixcan_output"
)

smultixcan_fdrreg_dir <- file.path(
  base_output_path,
  target_name,
  "09.smultixcan_fdrreg"
)

# ---- Load original SmultiXcan results ---- #

cat("Loading original SmultiXcan results and reference gene list...\n")

original_smultixcan_gene_list <- NULL

original_smultixcan_file <- file.path(
  smultixcan_fdrreg_dir,
  paste0(target_name, ".gene.bio.fdrreg.txt")
)

if (file.exists(original_smultixcan_file)) {
  original_smultixcan_results <- fread(original_smultixcan_file)

  if (!"ENSEMBL_GENE_ID" %in% names(original_smultixcan_results)) {
    stop(
      "ENSEMBL_GENE_ID column is missing from: ",
      original_smultixcan_file
    )
  }

  original_smultixcan_gene_list <- strip_gene_version(
    original_smultixcan_results$ENSEMBL_GENE_ID
  )

  if (anyDuplicated(original_smultixcan_gene_list)) {
    stop(
      paste0(
        "Duplicated ENSEMBL_GENE_ID values found in the original ",
        "SmultiXcan reference results after version stripping."
      )
    )
  }

  smultixcan_qval_total <- nrow(original_smultixcan_results)

  if ("qval" %in% names(original_smultixcan_results)) {
    smultixcan_qval_n_sig <- sum(
      original_smultixcan_results$qval < sig_threshold,
      na.rm = TRUE
    )
  } else {
    warning("qval column not found in original SmultiXcan results.")
  }

  cat(sprintf(
    "Original SmultiXcan genes: %d\n",
    smultixcan_qval_total
  ))
  cat(sprintf(
    "Original SmultiXcan qval < %.2f: %s / %d\n",
    sig_threshold,
    ifelse(
      is.na(smultixcan_qval_n_sig),
      "NA",
      smultixcan_qval_n_sig
    ),
    smultixcan_qval_total
  ))
} else {
  warning(
    "Original SmultiXcan results file not found: ",
    original_smultixcan_file,
    "\nA common gene list will be constructed as a fallback."
  )
}

# ---- Load target SmultiXcan output ---- #

cat("\nLoading SmultiXcan gene output files...\n")

target_smultixcan_file <- file.path(
  smultixcan_output_dir,
  paste0(target_name, ".allbrain.txt")
)

if (!file.exists(target_smultixcan_file)) {
  warning(
    "Target SmultiXcan file not found: ",
    target_smultixcan_file
  )
} else {
  target_header <- names(
    fread(target_smultixcan_file, nrows = 0L)
  )

  target_columns <- c("gene", "gene_name", "pvalue")
  missing_target_columns <- setdiff(
    target_columns,
    target_header
  )

  if (length(missing_target_columns) > 0L) {
    stop(
      "Required columns missing from target SmultiXcan file: ",
      paste(missing_target_columns, collapse = ", ")
    )
  }

  target_smultixcan <- fread(
    target_smultixcan_file,
    select = target_columns
  )

  target_smultixcan[, gene_stripped := strip_gene_version(gene)]

  # ---- Load trait SmultiXcan outputs ---- #

  trait_smultixcan_data <- list()
  valid_smultixcan_traits <- character(0)

  for (trait in all_traits) {
    trait_file <- file.path(
      smultixcan_output_dir,
      paste0(trait, ".allbrain.txt")
    )

    if (!file.exists(trait_file)) {
      warning(sprintf(
        "  SmultiXcan file not found: %s",
        trait_file
      ))
      next
    }

    trait_header <- names(fread(trait_file, nrows = 0L))
    required_columns <- c("gene", "pvalue")
    missing_columns <- setdiff(
      required_columns,
      trait_header
    )

    if (length(missing_columns) > 0L) {
      warning(sprintf(
        "Skipping SmultiXcan trait '%s'; missing columns: %s",
        trait,
        paste(missing_columns, collapse = ", ")
      ))
      next
    }

    dt <- fread(
      trait_file,
      select = required_columns
    )

    dt[, gene_stripped := strip_gene_version(gene)]

    trait_smultixcan_data[[trait]] <- dt
    valid_smultixcan_traits <- c(
      valid_smultixcan_traits,
      trait
    )

    cat(sprintf(
      "  Loaded SmultiXcan: %s\n",
      trait
    ))
  }

  if (length(valid_smultixcan_traits) == 0L) {
    warning("No valid SmultiXcan trait files found.")
  } else {
    # Use the original gene list when available.
    if (!is.null(original_smultixcan_gene_list)) {
      reference_smultixcan_genes <- original_smultixcan_gene_list

      cat(sprintf(
        "Using original SmultiXcan gene list: %d genes\n",
        length(reference_smultixcan_genes)
      ))
    } else {
      reference_smultixcan_genes <- Reduce(
        intersect,
        c(
          list(target_smultixcan$gene_stripped),
          lapply(
            trait_smultixcan_data[valid_smultixcan_traits],
            `[[`,
            "gene_stripped"
          )
        )
      )

      reference_smultixcan_genes <- sort(
        unique(reference_smultixcan_genes)
      )

      cat(sprintf(
        "Using fallback common SmultiXcan gene list: %d genes\n",
        length(reference_smultixcan_genes)
      ))
    }

    if (length(reference_smultixcan_genes) == 0L) {
      warning("No common SmultiXcan genes found.")
    } else {
      target_smultixcan <- align_to_reference(
        dt = target_smultixcan,
        key_col = "gene_stripped",
        reference_keys = reference_smultixcan_genes,
        data_label = paste0(
          "Target SmultiXcan output for ",
          target_name
        )
      )

      trait_smultixcan_data <- lapply(
        valid_smultixcan_traits,
        function(trait) {
          align_to_reference(
            dt = trait_smultixcan_data[[trait]],
            key_col = "gene_stripped",
            reference_keys = reference_smultixcan_genes,
            data_label = paste0(
              "SmultiXcan output for ",
              trait
            )
          )
        }
      )

      names(trait_smultixcan_data) <- valid_smultixcan_traits

      # Build feature matrix from unsigned p-value-derived z-scores.
      feature_matrix_smultixcan <- do.call(
        cbind,
        lapply(
          trait_smultixcan_data,
          function(dt) {
            p_to_z_safe(dt$pvalue)
          }
        )
      )

      if (is.null(dim(feature_matrix_smultixcan))) {
        feature_matrix_smultixcan <- matrix(
          feature_matrix_smultixcan,
          ncol = 1L
        )
      }

      colnames(feature_matrix_smultixcan) <- valid_smultixcan_traits
      storage.mode(feature_matrix_smultixcan) <- "double"

      # Assign random signs to the target, matching the original code.
      target_z_smultixcan_unsigned <- p_to_z_safe(
        target_smultixcan$pvalue
      )

      set.seed(random_seed)

      target_z_smultixcan <- target_z_smultixcan_unsigned *
        sign(rnorm(length(target_z_smultixcan_unsigned)))

      cat(sprintf(
        "SmultiXcan feature matrix: %d x %d\n",
        nrow(feature_matrix_smultixcan),
        ncol(feature_matrix_smultixcan)
      ))

      cat("Running FDRreg (theoretical null) for SmultiXcan...\n")

      fdr_smultixcan_theoretical <- FDRreg(
        target_z_smultixcan,
        feature_matrix_smultixcan,
        nulltype = "theoretical",
        method = "pr"
      )

      fdr_smultixcan <- fdr_smultixcan_theoretical$FDR

      smultixcan_fdr_n_sig <- sum(
        fdr_smultixcan < sig_threshold,
        na.rm = TRUE
      )

      smultixcan_total <- length(fdr_smultixcan)

      cat(sprintf(
        "SmultiXcan fdr.the < %.2f: %d / %d\n",
        sig_threshold,
        smultixcan_fdr_n_sig,
        smultixcan_total
      ))

      smultixcan_results_dt <- data.table(
        ENSEMBL_GENE_ID = target_smultixcan$gene_stripped,
        fdr_the = fdr_smultixcan
      )

      fwrite(
        smultixcan_results_dt,
        file.path(
          target_output_dir,
          paste0(
            target_name,
            "_smultixcan_fdr_the.csv"
          )
        )
      )
    }
  }
}

