safe_ratio <- function(numerator, denominator) {
  if (
    is.na(numerator) ||
    is.na(denominator) ||
    denominator <= 0
  ) {
    return(NA_real_)
  }

  numerator / denominator
}

combined_summary <- data.frame(
  analysis = c(
    "snp",
    "magma",
    "smultixcan"
  ),
  fdr_the_n_sig = c(
    snp_fdr_n_sig,
    magma_fdr_n_sig,
    smultixcan_fdr_n_sig
  ),
  fdr_the_total = c(
    snp_total,
    magma_total,
    smultixcan_total
  ),
  qval_n_sig = c(
    snp_qval_n_sig,
    magma_qval_n_sig,
    smultixcan_qval_n_sig
  ),
  qval_total = c(
    snp_qval_total,
    magma_qval_total,
    smultixcan_qval_total
  ),
  sensitivity_ratio = c(
    safe_ratio(
      snp_fdr_n_sig,
      snp_qval_n_sig
    ),
    safe_ratio(
      magma_fdr_n_sig,
      magma_qval_n_sig
    ),
    safe_ratio(
      smultixcan_fdr_n_sig,
      smultixcan_qval_n_sig
    )
  ),
  stringsAsFactors = FALSE
)

